import React, { useEffect, useState } from "react";
import axios from "axios";

function App() {
  const [medicines, setMedicines] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    async function loadMedicines() {
      try {
        const res = await axios.get("http://localhost:5000/api/medicines");
        setMedicines(res.data || []);
      } catch (err) {
        setError("Cannot load medicines. Is backend running?");
      }
    }
    loadMedicines();
  }, []);

  return (
    <div style={{ padding: 20, fontFamily: "Arial, sans-serif" }}>
      <h1>Online Medical Store</h1>
      <p>Frontend running successfully.</p>
      {error && <p style={{ color: "red" }}>{error}</p>}

      <h2>Medicines</h2>
      {medicines.length === 0 ? (
        <p>No medicines yet. Add one via backend API or SQL seed.</p>
      ) : (
        <ul>
          {medicines.map((m) => (
            <li key={m.id}>{m.name} | {m.brand} | ${m.price} | stock: {m.stock}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default App;
